import java.util.*;
public class Main {
  public static void main(String[] args) {
    Map<String,Integer> cache = new LinkedHashMap<>(16, .75f, true);
    for (String key : List.of("a","b","c","a","d")) {
      cache.put(key, key.length());
      if (cache.size() > 3) cache.remove(cache.keySet().iterator().next());
    }
    System.out.println(cache.keySet());
  }
}
